    $title = trim($_POST['title']);
    $initial_post = trim($_POST['content']);

    if (!empty($title) && !empty($initial_post)) {
        // Start a transaction so both Topic and First Post are created together
        $pdo->beginTransaction();

        $stmt = $pdo->prepare('INSERT INTO topics (title, user_id) VALUES (?, ?)');
        $stmt->execute([$title, $_SESSION['user_id']]);
        $topic_id = $pdo->lastInsertId();

        $stmt = $pdo->prepare('INSERT INTO posts (content, topic_id, user_id) VALUES (?, ?, ?)');
        $stmt->execute([$initial_post, $topic_id, $_SESSION['user_id']]);

        $pdo->commit();
    }
}

// Fetch all topics with the creator's username
$query = "SELECT topics.*, users.username FROM topics 
          JOIN users ON topics.user_id = users.id 
          ORDER BY topics.created_at DESC";
$topics = $pdo->query($query)->fetchAll();
?>

